css:
.heart-container {
  position: relative;
  display: inline-block;
  -webkit-tap-highlight-color: transparent;
  width: 150px;
  height: 150px;
  --fill: 100%;
}

.heart-container input[type="radio"] {
  display: none !important;
}

.click-layers {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 100;
}

.layer {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  cursor: pointer;
  display: none;
}

.click-layers .layer-1 {
  display: block;
}

#step1:checked ~ .click-layers .layer-1 {
  display: none;
}
#step1:checked ~ .click-layers .layer-2 {
  display: block;
}

#step2:checked ~ .click-layers .layer-2 {
  display: none;
}
#step2:checked ~ .click-layers .layer-3 {
  display: block;
}

#step3:checked ~ .click-layers .layer-3 {
  display: none;
}
#step3:checked ~ .click-layers .layer-4 {
  display: block;
}

#step4:checked ~ .click-layers .layer-4 {
  display: none;
}
#step4:checked ~ .click-layers .layer-5 {
  display: block;
}

#step5:checked ~ .click-layers .layer-5 {
  display: none;
}
#step5:checked ~ .click-layers .layer-reset {
  display: block !important;
  z-index: 200 !important;
}

#step0:checked ~ .click-layers .layer-1 {
  display: block;
}
#step0:checked ~ .click-layers .layer-2,
#step0:checked ~ .click-layers .layer-3,
#step0:checked ~ .click-layers .layer-4,
#step0:checked ~ .click-layers .layer-5,
#step0:checked ~ .click-layers .layer-reset {
  display: none;
}

#step1:checked ~ .cute-heart {
  --fill: 80%;
}
#step2:checked ~ .cute-heart {
  --fill: 60%;
}
#step3:checked ~ .cute-heart {
  --fill: 40%;
}
#step4:checked ~ .cute-heart {
  --fill: 20%;
}
#step5:checked ~ .cute-heart {
  --fill: 0%;
}

.click-layers:active ~ .cute-heart {
  transform: scale(0.9);
  transition: transform 0.1s ease;
}

.cute-heart {
  width: 100%;
  height: 100%;
  display: block;
  transform-origin: center;
  transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
  animation: floatHeart 3s ease-in-out infinite;
}

.color-layer {
  clip-path: polygon(0 var(--fill), 100% var(--fill), 100% 100%, 0 100%);
  transition: clip-path 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.smile-closed {
  transition: opacity 0.2s ease;
}

.smile-open {
  opacity: 0;
  transform: scale(0.5);
  transform-origin: 50px 55px;
  transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

#step5:checked ~ .cute-heart .smile-closed {
  opacity: 0;
}
#step5:checked ~ .cute-heart .smile-open {
  opacity: 1;
  transform: scale(1);
}

.particles-layer {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 1px;
  height: 1px;
  z-index: 1;
  pointer-events: none;
}

.particle {
  position: absolute;
  width: var(--w);
  height: var(--h);
  background-color: var(--color);
  border-radius: 2px;
  top: -10px;
  left: -4px;
  opacity: 0;
  transform: scale(0);
}

#step5:checked ~ .particles-layer .particle {
  animation: explode 4.5s cubic-bezier(0.1, 1, 0.3, 1) forwards;
}

@keyframes explode {
  0% {
    transform: rotate(var(--angle)) translateY(0) scale(0);
    opacity: 1;
  }
  15% {
    transform: rotate(var(--angle)) translateY(var(--dist)) scale(1);
    opacity: 1;
  }
  100% {
    transform: rotate(var(--angle)) translateY(var(--dist)) scale(0);
    opacity: 0;
  }
}

@keyframes floatHeart {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-8px);
  }
}
